177: static int idma_find_iova(struct iommu_domain *domain, size_t size,
178: 			  unsigned long *src_iova, unsigned long *dst_iova)
179: {
180: 	unsigned long start = domain->geometry.aperture_start;
181: 	unsigned long end = domain->geometry.aperture_end;
182: 	unsigned long iova;
183: 	size_t span = size * 2;
184: 
185: 	if (end < start || span < size || span - 1 > end - start)
186: 		return -EBUSY;
187: 
188: 	iova = ALIGN_DOWN(end - span + 1, SZ_2M);
189: 	for (;;) {
190: 		if (!idma_iova_range_free(domain, iova, span)) {
191: 			if (iova < start + SZ_2M)
192: 				break;
193: 			iova -= SZ_2M;
194: 			continue;
195: 		}
196: 
197: 		*src_iova = iova;
198: 		*dst_iova = iova + size;
199: 		return 0;
200: 	}
201: 
202: 	return -EBUSY;
203: }
