205: static int idma_iommu_map_range(struct iommu_domain *domain,
206: 				unsigned long iova, phys_addr_t phys,
207: 				size_t size, size_t pgsize)
208: {
209: 	size_t off;
210: 	int ret;
211: 
212: 	for (off = 0; off < size; off += pgsize) {
213: 		ret = iommu_map(domain, iova + off, phys + off, pgsize,
214: 				IOMMU_READ | IOMMU_WRITE, GFP_KERNEL);
215: 		if (ret) {
216: 			while (off) {
217: 				off -= pgsize;
218: 				iommu_unmap(domain, iova + off, pgsize);
219: 			}
220: 			return ret;
221: 		}
222: 	}
223: 
224: 	return 0;
225: }
