261: static u64 idma_pattern(struct idma_stream *s, size_t word)
262: {
263: 	return (0xa53c691df027b84eULL ^
264: 		((u64)s->idma->id * 0x0101010101010101ULL) ^
265: 		((u64)word * 0x9e3779b97f4a7c15ULL));
