268: static void idma_stream_cleanup(struct idma_stream *s)
269: {
270: 	if (!s->dev || s->retain)
271: 		return;
272: 	if (s->mapped_dst)
273: 		idma_iommu_unmap_range(s->domain, s->dst_iova, s->size, PAGE_SIZE);
274: 	if (s->mapped_src)
275: 		idma_iommu_unmap_range(s->domain, s->src_iova, s->size, PAGE_SIZE);
276: 	if (s->dst)
277: 		dma_free_attrs(s->dev, s->size, s->dst, s->dst_dma,
278: 			       DMA_ATTR_FORCE_CONTIGUOUS);
279: 	if (s->src)
280: 		dma_free_attrs(s->dev, s->size, s->src, s->src_dma,
281: 			       DMA_ATTR_FORCE_CONTIGUOUS);
282: }
