284: static int idma_stream_prepare(struct idma_stream *s, struct idma_device *idma,
285: 			       u32 pages, u32 chunk,
286: 			       struct idma_experiment_stats *stats)
287: {
288: 	struct page *src_page, *dst_page;
289: 	size_t i;
290: 	int ret;
291: 
292: 	s->idma = idma;
293: 	s->dev = idma->miscdev.parent;
294: 	s->stats = stats;
295: 	s->domain = iommu_get_domain_for_dev(s->dev);
296: 	if (!s->domain || s->domain->type == IOMMU_DOMAIN_IDENTITY)
297: 		return -EOPNOTSUPP;
298: 	s->size = (size_t)pages * PAGE_SIZE;
299: 	s->chunk = chunk;
300: 	s->src = dma_alloc_attrs(s->dev, s->size, &s->src_dma, GFP_KERNEL,
301: 				 DMA_ATTR_FORCE_CONTIGUOUS);
302: 	if (!s->src)
303: 		return -ENOMEM;
304: 	s->dst = dma_alloc_attrs(s->dev, s->size, &s->dst_dma, GFP_KERNEL,
305: 				 DMA_ATTR_FORCE_CONTIGUOUS);
306: 	if (!s->dst)
307: 		return -ENOMEM;
308: 	for (i = 0; i < s->size / sizeof(u64); i++) {
309: 		((u64 *)s->src)[i] = idma_pattern(s, i);
310: 		((u64 *)s->dst)[i] = ~idma_pattern(s, i);
311: 	}
312: 	src_page = idma_buffer_page(s->src);
313: 	dst_page = idma_buffer_page(s->dst);
314: 	if (!src_page || !dst_page)
315: 		return -EFAULT;
316: 	ret = idma_find_iova(s->domain, s->size, &s->src_iova, &s->dst_iova);
317: 	if (ret)
318: 		return ret;
319: 	ret = idma_iommu_map_range(s->domain, s->src_iova,
320: 				  page_to_phys(src_page), s->size, PAGE_SIZE);
321: 	if (ret)
322: 		return ret;
323: 	s->mapped_src = true;
324: 	ret = idma_iommu_map_range(s->domain, s->dst_iova,
325: 				  page_to_phys(dst_page), s->size, PAGE_SIZE);
326: 	if (ret)
327: 		return ret;
328: 	s->mapped_dst = true;
329: 	return 0;
330: }
