131: static int riscv_iommu_map_pages(struct io_pgtable_ops *ops,
132: 				 unsigned long iova, phys_addr_t phys,
133: 				 size_t pgsize, size_t pgcount, int prot,
134: 				 gfp_t gfp, size_t *mapped)
135: {
136: 	struct riscv_iommu_domain *domain = io_pgtable_ops_to_domain(ops);
137: 	size_t size = 0;
138: 	size_t page_size = get_page_size(pgsize);
139: 	pte_t *pte;
140: 	pte_t pte_val;
141: 	pgprot_t pte_prot;
142: 
143: 	if (domain->domain.type == IOMMU_DOMAIN_BLOCKED)
144: 		return -ENODEV;
145: 
146: 	if (domain->domain.type == IOMMU_DOMAIN_IDENTITY) {
147: 		*mapped = pgsize * pgcount;
148: 		return 0;
149: 	}
150: 
151: 	pte_prot = (prot & IOMMU_WRITE) ?
152: 	    __pgprot(_PAGE_BASE | _PAGE_READ | _PAGE_WRITE | _PAGE_DIRTY) :
153: 	    __pgprot(_PAGE_BASE | _PAGE_READ);
154: 
155: 	while (pgcount--) {
156: 		pte =
157: 		    riscv_iommu_pt_walk_alloc((pmd_t *) domain->pgd_root, iova,
158: 					      PGDIR_SHIFT, true, page_size,
159: 					      get_zeroed_page, gfp);
160: 		if (!pte) {
161: 			*mapped = size;
162: 			return -ENOMEM;
163: 		}
164: 
165: 		pte_val = pfn_pte(phys_to_pfn(phys), pte_prot);
166: 
167: 		set_pte(pte, pte_val);
168: 
169: 		size += page_size;
170: 		iova += page_size;
171: 		phys += page_size;
172: 	}
173: 
174: 	*mapped = size;
175: 	return 0;

178: static size_t riscv_iommu_unmap_pages(struct io_pgtable_ops *ops,
179: 				      unsigned long iova, size_t pgsize,
180: 				      size_t pgcount,
181: 				      struct iommu_iotlb_gather *gather)
182: {
183: 	struct riscv_iommu_domain *domain = io_pgtable_ops_to_domain(ops);
184: 	size_t size = 0;
185: 	size_t page_size = get_page_size(pgsize);
186: 	pte_t *pte;
187: 
188: 	if (domain->domain.type == IOMMU_DOMAIN_IDENTITY)
189: 		return pgsize * pgcount;
190: 
191: 	while (pgcount--) {
192: 		pte = riscv_iommu_pt_walk_fetch((pmd_t *) domain->pgd_root,
193: 						iova, PGDIR_SHIFT, true, NULL);
194: 		if (!pte)
195: 			return size;
196: 
197: 		set_pte(pte, __pte(0));
198: 
199: 		iommu_iotlb_gather_add_page(&domain->domain, gather, iova,
200: 					    pgsize);
201: 
202: 		size += page_size;
203: 		iova += page_size;
204: 	}
205: 
206: 	return size;
207: }
